private void btnCalculateActionPerformed(java.awt.event.ActionEvent evt) {
    try {
        // Step 1: Read numeric inputs
        double unitPrice = Double.parseDouble(txtUnitPrice.getText().trim());
        int quantity = Integer.parseInt(txtQuantity.getText().trim());

        if (unitPrice < 0 || quantity <= 0) {
            javax.swing.JOptionPane.showMessageDialog(this, 
                "Price and Quantity must be positive values!", 
                "Input Error", javax.swing.JOptionPane.WARNING_MESSAGE);
            return;
        }

        // Step 2: Compute base amount
        double baseAmount = unitPrice * quantity;

        // Step 3: Check warranty checkbox
        double warrantyCost = 0.0;
        if (chkWarranty.isSelected()) {
            warrantyCost = 500.0;
        }

        // Step 4: Grand total
        double grandTotal = baseAmount + warrantyCost;

        // Step 5: Display result
        txtGrandTotal.setText(String.format("₹ %.2f", grandTotal));

    } catch (NumberFormatException ex) {
        javax.swing.JOptionPane.showMessageDialog(this, 
            "Please enter valid numbers for Price and Quantity!", 
            "Error", javax.swing.JOptionPane.ERROR_MESSAGE);
    }
}
```

